ALTER TABLE "Order" ADD CONSTRAINT "Order_currency" CHECK ("currency" = 'USD');
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_unitMinor_bounds" CHECK ("unitMinor" BETWEEN 0 AND 999999999999);
