ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_currency" CHECK ("currency" = 'USD');
ALTER TABLE "Capture" ADD CONSTRAINT "Capture_grossMinor_bounds" CHECK ("grossMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "Capture" ADD CONSTRAINT "Capture_reservedMinor_bounds" CHECK ("reservedMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "Capture" ADD CONSTRAINT "Capture_refundedMinor_bounds" CHECK ("refundedMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "Capture" ADD CONSTRAINT "Capture_externalRefundedMinor_bounds" CHECK ("externalRefundedMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "Capture" ADD CONSTRAINT "Capture_currency" CHECK ("currency" = 'USD');
ALTER TABLE "Evidence" ADD CONSTRAINT "Evidence_sizeBytes_bounds" CHECK ("sizeBytes" BETWEEN 0 AND 999999999999);
ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_amountMinor_bounds" CHECK ("amountMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "Proposal" ADD CONSTRAINT "Proposal_currency" CHECK ("currency" = 'USD');
ALTER TABLE "RefundOperation" ADD CONSTRAINT "RefundOperation_amountMinor_bounds" CHECK ("amountMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "RefundOperation" ADD CONSTRAINT "RefundOperation_currency" CHECK ("currency" = 'USD');
ALTER TABLE "ExternalRefund" ADD CONSTRAINT "ExternalRefund_amountMinor_bounds" CHECK ("amountMinor" BETWEEN 0 AND 999999999999);
ALTER TABLE "ExternalRefund" ADD CONSTRAINT "ExternalRefund_currency" CHECK ("currency" = 'USD');
ALTER TABLE "Capture" ADD CONSTRAINT "capture_balance" CHECK ("refundedMinor" + "externalRefundedMinor" + "reservedMinor" <= "grossMinor");
ALTER TABLE "RefundOperation" ADD CONSTRAINT "refund_positive" CHECK ("amountMinor" > 0);
ALTER TABLE "ExternalRefund" ADD CONSTRAINT "external_positive" CHECK ("amountMinor" > 0);
ALTER TABLE "OrderItem" ADD CONSTRAINT "quantity_positive" CHECK ("quantity" > 0);
ALTER TABLE "EvidenceChunk" ADD CONSTRAINT "chunk_bounds" CHECK ("charStart" >= 0 AND "charEnd" >= "charStart" AND ("page" IS NULL OR "page">0));
ALTER TABLE "Evidence" ADD CONSTRAINT "evidence_limit" CHECK ("sizeBytes" > 0 AND "sizeBytes" <= 10485760);
ALTER TABLE "FindingReference" ADD CONSTRAINT "exact_reference" CHECK (num_nonnulls("evidenceChunkId","orderId","captureId","policyClauseId") = 1);
ALTER TABLE "PaymentAttempt" ADD CONSTRAINT "one_operation" CHECK (num_nonnulls("refundOperationId","checkoutOperationId")=1 AND "attemptNo">0);
ALTER TABLE "Proposal" ADD CONSTRAINT "proposal_money" CHECK ((("kind" IN ('FULL_REFUND','PARTIAL_REFUND') AND "amountMinor">0 AND "currency" IS NOT NULL) OR ("kind" NOT IN ('FULL_REFUND','PARTIAL_REFUND') AND "amountMinor" IS NULL AND "currency" IS NULL)));
CREATE UNIQUE INDEX "case_one_active" ON "Case" ("merchantId","orderId") WHERE "status" NOT IN ('RESOLVED','CLOSED_WITHOUT_AGREEMENT');
CREATE UNIQUE INDEX "checkout_active_kind" ON "CheckoutOperation" ("merchantId","orderId","kind") WHERE "state" <> 'FAILED';
CREATE UNIQUE INDEX "attempt_refund_no" ON "PaymentAttempt" ("refundOperationId","attemptNo") WHERE "refundOperationId" IS NOT NULL;
CREATE UNIQUE INDEX "attempt_checkout_no" ON "PaymentAttempt" ("checkoutOperationId","attemptNo") WHERE "checkoutOperationId" IS NOT NULL;
CREATE UNIQUE INDEX "order_owner_identity" ON "Order" ("merchantId",id,"customerUserId");
ALTER TABLE "CustomerOrder" ADD CONSTRAINT "ownership_matches_order" FOREIGN KEY ("merchantId","orderId","userId") REFERENCES "Order" ("merchantId",id,"customerUserId");
CREATE UNIQUE INDEX "capture_currency_identity" ON "Capture" ("merchantId",id,currency);
ALTER TABLE "RefundOperation" ADD CONSTRAINT "refund_capture_currency" FOREIGN KEY ("merchantId","captureId",currency) REFERENCES "Capture" ("merchantId",id,currency);
CREATE INDEX "case_worklist" ON "Case" ("merchantId",status,"createdAt" DESC,id);
CREATE INDEX "order_customer" ON "Order" ("merchantId","customerUserId","createdAt" DESC,id);
CREATE INDEX "membership_discovery" ON "Membership" ("userId",active);
